function parseCsvLine(line) { const values = []; let value = ''; let quoted = false; for (let index = 0; index < line.length; index += 1) { const character = line[index]; if (character === '"' && line[index + 1] === '"') { value += '"'; index += 1; } else if (character === '"') quoted = !quoted; else if (character === ',' && !quoted) { values.push(value.trim()); value = ''; } else value += character; } values.push(value.trim()); return values; }
function parseCloudFile(text, filename) { if (filename.toLowerCase().endsWith('.csv')) { const lines = text.split(/\r?\n/).filter(Boolean).map(parseCsvLine); if (!lines.length) return { records: [] }; const headers = lines.shift().map((header) => header.toLowerCase().replaceAll(/[^a-z0-9]/g, '')); const aliases = { provider: 'provider', cloudprovider: 'provider', account: 'accountId', accountid: 'accountId', accountname: 'accountName', region: 'region', availabilityzone: 'availabilityZone', resourcetype: 'resourceType', type: 'resourceType', resourceid: 'resourceId', id: 'resourceId', name: 'name', status: 'status', privateip: 'privateIp', publicip: 'publicIp' }; return { records: lines.map((line) => Object.fromEntries(line.map((value, index) => [aliases[headers[index]] || headers[index], value]))) }; } const parsed = JSON.parse(text); return Array.isArray(parsed) ? { records: parsed } : parsed; }
async function importCloudFile(event) { const file = event.target.files[0]; if (!file) return; let payload; try { payload = parseCloudFile(await file.text(), file.name); } catch { toast('That cloud file is not valid JSON or CSV.'); event.target.value = ''; return; } const response = await fetch('/api/cloud/import', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(payload) }); if (!response.ok) { const result = await response.json(); toast(result.error || 'Cloud import failed.'); return; } const result = await response.json(); await refresh(); toast(`Imported ${result.counts.valid} cloud resource${result.counts.valid === 1 ? '' : 's'}; ${result.counts.invalid} invalid.`); event.target.value = ''; }
function renderCloud() { const resources = snapshot?.cloudResources || []; const sites = snapshot?.cloudSites || []; const search = ($('#cloud-search')?.value || '').trim().toLowerCase(); const provider = $('#cloud-provider-filter')?.value || 'all'; const region = $('#cloud-region-filter')?.value || 'all'; const type = $('#cloud-type-filter')?.value || 'all'; const setOptions = (id, values, label) => { const select = $(`#${id}`); if (!select) return; const current = select.value; select.innerHTML = `<option value="all">${label}</option>${values.sort().map((value) => `<option value="${escapeHtml(value)}">${escapeHtml(value)}</option>`).join('')}`; select.value = values.includes(current) ? current : 'all'; }; setOptions('cloud-provider-filter', [...new Set(resources.map((resource) => resource.provider))], 'All providers'); setOptions('cloud-region-filter', [...new Set(resources.map((resource) => resource.region))], 'All regions'); setOptions('cloud-type-filter', [...new Set(resources.map((resource) => resource.resourceType))], 'All resource types'); const filtered = resources.filter((resource) => { const haystack = `${resource.name} ${resource.resourceId} ${resource.accountName} ${resource.accountId} ${resource.region} ${resource.resourceType}`.toLowerCase(); return (provider === 'all' || resource.provider === provider) && (region === 'all' || resource.region === region) && (type === 'all' || resource.resourceType === type) && (!search || haystack.includes(search)); }); $('#cloud-metrics').innerHTML = [['CLOUD SITES', sites.length, 'Imported accounts'], ['RESOURCES', resources.length, `${filtered.length} shown`], ['PROVIDERS', new Set(resources.map((resource) => resource.provider)).size, 'Provider-neutral'], ['REGIONS', new Set(resources.map((resource) => resource.region)).size, 'Across accounts']].map(([label, value, note]) => `<div class="metric"><div class="metric-top"><span>${label}</span><span class="metric-icon">☁</span></div><div class="metric-value">${value}</div><div class="metric-note">${note}</div></div>`).join(''); $('#cloud-table-body').innerHTML = filtered.length ? filtered.map((resource) => `<tr><td><strong>${escapeHtml(resource.name)}</strong><small>${escapeHtml(resource.tags?.Name || '')}</small></td><td><span class="device-type-pill">${escapeHtml(resource.resourceType)}</span></td><td><strong>${escapeHtml(resource.provider.toUpperCase())}</strong><small>${escapeHtml(resource.accountName || resource.accountId)}</small></td><td>${escapeHtml(resource.region)}<small>${escapeHtml(resource.availabilityZone || '—')}</small></td><td><span class="health-label"><i class="health-dot ${resource.status === 'running' || resource.status === 'available' ? 'online' : 'unknown'}"></i>${escapeHtml(resource.status)}</span></td><td><code>${escapeHtml(resource.resourceId)}</code></td><td><button class="button secondary cloud-site-open" data-site-id="${resource.cloudSiteId}">Site</button></td></tr>`).join('') : '<tr><td colspan="7"><div class="empty">Import cloud inventory to see resources here.</div></td></tr>'; document.querySelectorAll('.cloud-site-open').forEach((button) => button.addEventListener('click', () => openCloudSite(button.dataset.siteId))); }
function openCloudSite(siteId) { const site = (snapshot.cloudSites || []).find((item) => item.id === siteId); const resources = (snapshot.cloudResources || []).filter((item) => item.cloudSiteId === siteId); const panel = $('#cloud-site-detail'); if (!site || !panel) return; panel.hidden = false; panel.innerHTML = `<div class="site-detail-heading"><div><p class="eyebrow accent">CLOUD SITE</p><h3>${escapeHtml(site.name)}</h3><p class="muted">${escapeHtml(site.provider.toUpperCase())} · ${escapeHtml(site.accountId)} · ${site.regions.length} regions</p></div><button class="text-button cloud-site-close">Close ×</button></div><div class="site-detail-grid"><div><p class="ip-section-label">REGIONS</p>${site.regions.map((region) => `<div class="detail-row"><strong>${escapeHtml(region)}</strong><span>${resources.filter((resource) => resource.region === region).length} resources</span></div>`).join('')}</div><div><p class="ip-section-label">RESOURCE TYPES</p>${[...new Set(resources.map((resource) => resource.resourceType))].map((resourceType) => `<div class="detail-row"><strong>${escapeHtml(resourceType)}</strong><span>${resources.filter((resource) => resource.resourceType === resourceType).length}</span></div>`).join('')}</div></div>`; panel.querySelector('.cloud-site-close').addEventListener('click', () => { panel.hidden = true; }); }
function topologyPosition(device, index) { return device.topologyPosition || { x: 70 + (index % 4) * 240, y: 70 + Math.floor(index / 4) * 160 }; }
function topologyEndpointName(endpoint, devices, groups) { if (endpoint?.startsWith('group:')) return groups.find((group) => `group:${group.id}` === endpoint)?.name || endpoint; return devices.find((device) => device.id === endpoint)?.name || endpoint; }
function enhanceOverviewSharedUnits() { const rack = snapshot.racks.find((item) => item.id === $('#overview-rack-select')?.value); const face = document.querySelector('.overview-rack-face'); if (!rack || !face) return; face.querySelectorAll('.overview-rack-slot').forEach((row, index) => { const unit = rack.height - index; const occupants = rack.devices.filter((device) => device.rackUnit === unit && device.rackWidth === 'half'); if (!occupants.length) return; const slot = (device, position) => device ? `<div class="overview-rack-half-slot filled" data-device-id="${device.id}" data-rack-position="${position}"><img src="${profileAsset(device)}" alt=""/><span><strong><i class="health-dot ${deviceHealth(device)}"></i>${escapeHtml(device.name)}</strong><small>${escapeHtml(device.address?.ip || 'No IP')} · ${escapeHtml(serviceSummary(device))}</small></span></div>` : `<div class="overview-rack-half-slot empty"><small>${position} side available</small></div>`; const left = occupants.find((device) => (device.rackPosition || 'left') === 'left'); const right = occupants.find((device) => device.rackPosition === 'right'); row.className = 'overview-rack-slot overview-shared-slot'; row.innerHTML = `${slot(left, 'left')}${slot(right, 'right')}`; }); document.querySelectorAll('.overview-rack-half-slot.filled').forEach((slot) => slot.addEventListener('click', () => openDeviceDetails(slot.dataset.deviceId))); }
function addTopologyServiceControls() { document.querySelectorAll('.topology-node').forEach((node) => { const device = snapshot.topology.devices.find((item) => item.id === node.dataset.deviceId); const services = (snapshot.services || []).filter((service) => service.deviceId === device?.id && service.status !== 'ignored' && service.topologyVisible !== false); node.classList.toggle('services-hidden', !services.length); node.querySelectorAll('.topology-app').forEach((app, index) => { const service = services[index]; if (!service || app.querySelector('.topology-service-toggle')) return; const button = document.createElement('button'); button.className = 'topology-service-toggle'; button.type = 'button'; button.textContent = 'Hide'; button.title = 'Hide service on topology'; button.addEventListener('click', async (event) => { event.stopPropagation(); const response = await fetch(`/api/services/${service.id}`, { method: 'PATCH', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ name: service.name, deviceId: service.deviceId, port: service.port, protocol: service.protocol, url: service.url || '', description: service.description || '', enabled: service.enabled !== false, overviewVisible: service.overviewVisible === true, topologyVisible: false }) }); if (response.ok) await refresh(); }); app.appendChild(button); }); }); }
function colorTopologyConnections() { const colors = ['#62d19a', '#63b3ed', '#d8a4ff', '#f6c86c', '#ff8b8b']; document.querySelectorAll('#topology-links line:not(.topology-drag-line)').forEach((line, index) => { line.style.stroke = colors[index % colors.length]; }); }
function bindTopologyServiceToggles() { document.querySelectorAll('.service-row').forEach((row) => { const edit = row.querySelector('.edit-service'); const service = snapshot.services.find((item) => item.id === edit?.dataset.id); if (!service || row.querySelector('.toggle-topology-service')) return; const button = document.createElement('button'); button.className = 'button secondary toggle-topology-service'; button.textContent = service.topologyVisible === false ? 'Show topology' : 'Hide topology'; button.addEventListener('click', async () => { const response = await fetch(`/api/services/${service.id}`, { method: 'PATCH', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ name: service.name, deviceId: service.deviceId, port: service.port, protocol: service.protocol, url: service.url || '', description: service.description || '', enabled: service.enabled !== false, overviewVisible: service.overviewVisible === true, topologyVisible: service.topologyVisible === false }) }); if (response.ok) await refresh(); }); row.querySelector('.service-actions')?.prepend(button); }); }
function bindDeviceTableDeletes() { document.querySelectorAll('#devices-table-body tr').forEach((row) => { const edit = row.querySelector('.edit-device-page'); if (!edit || row.querySelector('.delete-device-page')) return; const button = document.createElement('button'); button.className = 'button secondary delete-device-page'; button.textContent = 'Delete'; button.addEventListener('click', () => deleteDevice(edit.dataset.id)); edit.parentElement.appendChild(button); }); }
function labelTopologyConnections() { const links = snapshot.topology?.links || []; document.querySelectorAll('.topology-delete-link').forEach((button, index) => { const link = links[index]; const label = button.parentElement?.querySelector('span'); if (link && label) label.textContent = `${topologyEndpointName(link.sourceDeviceId, snapshot.topology.devices, snapshot.topology.groups || [])} → ${topologyEndpointName(link.targetDeviceId, snapshot.topology.devices, snapshot.topology.groups || [])}`; }); }
function ensureTopologyToolbarActions() { const toolbar = document.querySelector('.topology-toolbar'); if (!toolbar || $('#topology-save')) return; const save = document.createElement('button'); save.className = 'button secondary'; save.id = 'topology-save'; save.textContent = 'Save locations'; const resetLayout = document.createElement('button'); resetLayout.className = 'button secondary'; resetLayout.id = 'topology-reset-layout'; resetLayout.textContent = 'Reset locations'; const addInfra = document.createElement('button'); addInfra.className = 'button secondary'; addInfra.id = 'topology-add-infra'; addInfra.textContent = '+ Add infrastructure'; toolbar.insertBefore(addInfra, $('#topology-reset')); toolbar.insertBefore(save, $('#topology-reset')); toolbar.insertBefore(resetLayout, $('#topology-reset')); save.addEventListener('click', saveTopologyLocations); resetLayout.addEventListener('click', resetTopologyLocations); addInfra.addEventListener('click', addTopologyInfra); }
async function addTopologyInfra() { const choice = window.prompt('Infrastructure type: wall-panel, patch-panel-24, patch-panel-48, or cable-management', 'wall-panel'); if (!choice?.trim()) return; const visualProfile = choice.trim().toLowerCase(); const name = window.prompt('Label for this topology item', visualProfile.replaceAll('-', ' ')); if (!name?.trim()) return; const response = await fetch('/api/topology/infra', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ name, visualProfile }) }); if (response.ok) { await refresh(); toast('Topology infrastructure added.'); } else { const result = await response.json(); toast(result.error || 'Could not add topology infrastructure.'); } }
async function removeFromTopology(id) { const device = snapshot.devices.find((item) => item.id === id); if (!device || !window.confirm(`Remove ${device.name} from the topology? It will remain in inventory.`)) return; await saveTopologyPosition(id, null); toast(`${device.name} removed from topology.`); }
function decorateTopologyItems() { const groups = snapshot.topology?.groups || []; groups.filter((group) => group.kind === 'infra').forEach((group) => { const node = document.querySelector(`.topology-group[data-group-id="${group.id}"]`); if (!node) return; node.classList.add('topology-infra'); node.innerHTML = `<button class="topology-handle topology-handle-left" data-topology-source="group:${group.id}" title="Drag to connect"></button><button class="topology-handle topology-handle-right" data-topology-source="group:${group.id}" title="Drag to connect"></button><button class="topology-handle topology-handle-top" data-topology-source="group:${group.id}" title="Drag to connect"></button><button class="topology-handle topology-handle-bottom" data-topology-source="group:${group.id}" title="Drag to connect"></button><img src="${profileAsset({ visualProfile: group.visualProfile })}" alt=""/><strong>${escapeHtml(group.name)}</strong><button class="topology-delete-group" data-id="${group.id}" title="Remove from topology">×</button>`; }); document.querySelectorAll('.topology-node').forEach((node) => { if (!node.querySelector('.topology-handle-top')) node.insertAdjacentHTML('afterbegin', '<button class="topology-handle topology-handle-top" data-topology-source="' + node.dataset.deviceId + '" title="Drag to connect"></button><button class="topology-handle topology-handle-bottom" data-topology-source="' + node.dataset.deviceId + '" title="Drag to connect"></button>'); }); document.querySelectorAll('.topology-group:not(.topology-infra)').forEach((node) => { if (!node.querySelector('.topology-handle-top')) node.insertAdjacentHTML('afterbegin', '<button class="topology-handle topology-handle-top" data-topology-source="group:' + node.dataset.groupId + '" title="Drag to connect"></button><button class="topology-handle topology-handle-bottom" data-topology-source="group:' + node.dataset.groupId + '" title="Drag to connect"></button>'); }); }
function bindExtraTopologyHandles() { document.querySelectorAll('.topology-handle-top,.topology-handle-bottom').forEach((handle) => { if (handle.dataset.bound) return; handle.dataset.bound = 'true'; handle.addEventListener('pointerdown', (event) => startTopologyConnection(event, handle.dataset.topologySource)); handle.addEventListener('pointerup', (event) => { if (topologyConnectionDrag) { event.stopPropagation(); finishTopologyConnection(handle.dataset.topologySource); } }); }); }
async function saveTopologyLocations() { if (!snapshot?.topology?.devices) return; await Promise.all(snapshot.topology.devices.filter((device) => device.topologyPosition).map((device) => saveTopologyPosition(device.id, device.topologyPosition, false))); await refresh(); toast('Topology locations saved.'); }
async function resetTopologyLocations() { if (!window.confirm('Reset all device locations?')) return; await Promise.all(snapshot.topology.devices.map((device) => saveTopologyPosition(device.id, null, false))); await refresh(); toast('Topology locations reset.'); }
function renderTopologyLegacy() {
  if (!snapshot.topology || !$('#topology-canvas')) return;
  const { devices } = snapshot.topology;
  const groups = snapshot.topology.groups || [];
  const links = snapshot.topology.links || [];
  $('#topology-canvas').style.transform = `scale(${topologyScale})`;
  $('#topology-zoom-label').textContent = `${Math.round(topologyScale * 100)}%`;
  const positions = new Map(devices.map((device, index) => [device.id, topologyPosition(device, index)]));
  $('#topology-tray').innerHTML = `<h3>Unplaced devices</h3><p>Drag a device onto the canvas, or move an existing card to save its position.</p><div class="topology-tray-list">${devices.filter((device) => !device.topologyPosition).map((device) => `<div class="topology-tray-item" draggable="true" data-device-id="${device.id}"><img src="${profileAsset(device)}" alt=""/><span>${escapeHtml(device.name)}</span></div>`).join('') || '<div class="topology-empty">All devices are on the canvas.</div>'}</div><p class="ip-section-label">CONNECTIONS</p><div class="topology-tray-list">${links.map((link) => { const source = devices.find((device) => device.id === link.sourceDeviceId)?.name || link.sourceDeviceId; const target = devices.find((device) => device.id === link.targetDeviceId)?.name || link.targetDeviceId; return `<div class="topology-tray-item"><span>${escapeHtml(source)} → ${escapeHtml(target)}</span><button class="button secondary topology-delete-link" data-id="${link.id}">×</button></div>`; }).join('') || '<div class="topology-empty">No connections yet.</div>'}</div>`;
  $('#topology-groups').innerHTML = groups.map((group) => `<div class="topology-group" data-group-id="${group.id}" style="left:${group.x}px;top:${group.y}px;width:${group.width}px;height:${group.height}px;border-color:${escapeHtml(group.color)}"><div class="topology-group-heading">${escapeHtml(group.name)}</div><button class="topology-delete-group" data-id="${group.id}" title="Delete group">×</button></div>`).join('');
  $('#topology-nodes').innerHTML = devices.map((device, index) => { const position = positions.get(device.id); return `<article class="topology-node" draggable="false" data-device-id="${device.id}" style="left:${position.x}px;top:${position.y}px"><div class="topology-node-header"><img src="${profileAsset(device)}" alt=""/><div><strong><i class="health-dot ${deviceHealth(device)}"></i>${escapeHtml(device.name)}</strong><small>${escapeHtml(device.address?.ip || 'No IP assigned')}</small></div></div><small>${device.serviceCount || 0} services · ${escapeHtml(device.visualProfile || 'server-1u')}</small><div class="topology-node-actions"><button class="topology-edit-node" data-id="${device.id}">Edit</button><button class="topology-delete-node topology-delete" data-id="${device.id}">Delete</button></div></article>`; }).join('') || '<div class="topology-empty">Add devices to start mapping your lab.</div>';
  const svg = $('#topology-links');
  svg.innerHTML = links.map((link) => { const source = positions.get(link.sourceDeviceId); const target = positions.get(link.targetDeviceId); if (!source || !target) return ''; const direction = link.direction === 'forward' ? 'marker-end="url(#topology-arrow)"' : link.direction === 'backward' ? 'marker-start="url(#topology-arrow)"' : ''; return `<line x1="${source.x + 95}" y1="${source.y + 53}" x2="${target.x + 95}" y2="${target.y + 53}" ${direction}/>${link.label ? `<text x="${(source.x + target.x) / 2 + 95}" y="${(source.y + target.y) / 2 + 45}">${escapeHtml(link.label)}</text>` : ''}`; }).join('') + '<defs><marker id="topology-arrow" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L0,6 L7,3 z" fill="#62d19a"/></marker></defs>';
  document.querySelectorAll('.topology-tray-item[data-device-id]').forEach((item) => item.addEventListener('dragstart', (event) => event.dataTransfer.setData('text/plain', item.dataset.deviceId)));
  document.querySelectorAll('.topology-node').forEach((node) => attachTopologyDrag(node));
  document.querySelectorAll('.topology-edit-node').forEach((button) => button.addEventListener('click', (event) => { event.stopPropagation(); openResourceModal('device', snapshot.devices.find((device) => device.id === button.dataset.id)); }));
  document.querySelectorAll('.topology-delete-node').forEach((button) => button.addEventListener('click', (event) => { event.stopPropagation(); deleteDevice(button.dataset.id); }));
  document.querySelectorAll('.topology-delete-link').forEach((button) => button.addEventListener('click', () => deleteTopologyLink(button.dataset.id)));
  document.querySelectorAll('.topology-delete-group').forEach((button) => button.addEventListener('click', () => deleteTopologyGroup(button.dataset.id)));
  document.querySelectorAll('.topology-group').forEach((group) => attachTopologyGroupDrag(group));
}
function attachTopologyDrag(node) { let drag = null; node.addEventListener('pointerdown', (event) => { if (event.target.closest('button')) return; const position = { x: Number.parseFloat(node.style.left), y: Number.parseFloat(node.style.top) }; drag = { startX: event.clientX, startY: event.clientY, x: position.x, y: position.y }; node.setPointerCapture(event.pointerId); }); node.addEventListener('pointermove', (event) => { if (!drag) return; const x = drag.x + (event.clientX - drag.startX) / topologyScale; const y = drag.y + (event.clientY - drag.startY) / topologyScale; node.style.left = `${x}px`; node.style.top = `${y}px`; }); node.addEventListener('pointerup', async (event) => { if (!drag) return; const position = { x: Number.parseFloat(node.style.left), y: Number.parseFloat(node.style.top) }; drag = null; await saveTopologyPosition(node.dataset.deviceId, position); }); node.addEventListener('dblclick', () => openResourceModal('device', snapshot.devices.find((device) => device.id === node.dataset.deviceId))); }
function attachTopologyGroupDrag(group) { let drag = null; group.addEventListener('pointerdown', (event) => { if (event.target.closest('button')) return; drag = { startX: event.clientX, startY: event.clientY, x: Number.parseFloat(group.style.left), y: Number.parseFloat(group.style.top) }; group.setPointerCapture(event.pointerId); }); group.addEventListener('pointermove', (event) => { if (!drag) return; group.style.left = `${drag.x + (event.clientX - drag.startX) / topologyScale}px`; group.style.top = `${drag.y + (event.clientY - drag.startY) / topologyScale}px`; }); group.addEventListener('pointerup', async () => { if (!drag) return; const position = { x: Number.parseFloat(group.style.left), y: Number.parseFloat(group.style.top) }; const id = group.dataset.groupId; drag = null; await fetch(`/api/topology/groups/${id}`, { method: 'PATCH', headers: { 'content-type': 'application/json' }, body: JSON.stringify(position) }); }); }
async function saveTopologyPosition(id, position, refreshAfter = true) { const device = snapshot.devices.find((item) => item.id === id); if (!device) return; await fetch(`/api/devices/${id}`, { method: 'PATCH', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ name: device.name, role: device.role, deviceType: device.deviceType, visualProfile: device.visualProfile, topologyPosition: position, description: device.description, height: device.height, rackId: device.rackId || '', rackUnit: device.rackUnit || '', rackWidth: device.rackWidth || 'full', rackPosition: device.rackPosition || 'full', ip: device.address?.ip || '', networkId: device.address?.networkId || '', hostname: device.address?.hostname || '' }) }); if (refreshAfter) await refresh(); }
async function addTopologyGroup() { const name = window.prompt('Group name'); if (!name?.trim()) return; const response = await fetch('/api/topology/groups', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ name }) }); if (response.ok) { await refresh(); toast('Topology group added.'); } }
async function addTopologyLink() { if (snapshot.devices.length < 2) return toast('Add at least two devices first.'); const sourceName = window.prompt(`Source device name (${snapshot.devices.map((device) => device.name).join(', ')})`); const source = snapshot.devices.find((device) => device.name.toLowerCase() === sourceName?.trim().toLowerCase()); const targetName = window.prompt('Target device name'); const target = snapshot.devices.find((device) => device.name.toLowerCase() === targetName?.trim().toLowerCase()); if (!source || !target) return toast('Could not find both devices by name.'); const label = window.prompt('Connection label (optional)') || ''; const response = await fetch('/api/topology/links', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ sourceDeviceId: source.id, targetDeviceId: target.id, label }) }); if (response.ok) { await refresh(); toast('Connection added.'); } else { const result = await response.json(); toast(result.error || 'Could not add connection.'); } }
async function deleteTopologyLink(id) { if (!window.confirm('Remove this connection?')) return; const response = await fetch(`/api/topology/links/${id}`, { method: 'DELETE' }); if (response.ok) { await refresh(); toast('Connection removed.'); } }
async function deleteTopologyGroup(id) { if (!window.confirm('Remove this group? Devices will remain.')) return; const response = await fetch(`/api/topology/groups/${id}`, { method: 'DELETE' }); if (response.ok) { await refresh(); toast('Group removed.'); } }
async function refresh() { const [summaryResponse, topologyResponse] = await Promise.all([fetch('/api/summary'), fetch('/api/topology')]); snapshot = await summaryResponse.json(); snapshot.topology = await topologyResponse.json(); render(); if (healthTimer === null) healthTimer = setInterval(() => checkHealth(false), 30000); }
$('#topology-viewport').addEventListener('dragover', (event) => event.preventDefault()); $('#topology-viewport').addEventListener('drop', async (event) => { event.preventDefault(); const id = event.dataTransfer.getData('text/plain'); const rect = $('#topology-canvas').getBoundingClientRect(); const position = { x: (event.clientX - rect.left) / topologyScale - 95, y: (event.clientY - rect.top) / topologyScale - 53 }; await saveTopologyPosition(id, position); }); $('#topology-add-group').addEventListener('click', addTopologyGroup); $('#topology-add-link').addEventListener('click', addTopologyLink); $('#topology-zoom-in').addEventListener('click', () => { topologyScale = Math.min(1.6, topologyScale + .1); renderTopology(); }); $('#topology-zoom-out').addEventListener('click', () => { topologyScale = Math.max(.6, topologyScale - .1); renderTopology(); }); $('#topology-reset').addEventListener('click', () => { topologyScale = 1; $('#topology-viewport').scrollTo({ left: 0, top: 0, behavior: 'smooth' }); renderTopology(); });
