  if (type === 'service') payload.enabled = event.currentTarget.querySelector('[name="enabled"]').checked;
  const endpoint = editingDeviceId ? `/${editingResourceType === 'service' ? 'api/services' : 'api/devices'}/${editingDeviceId}` : `/api/${type}s`;
  const response = await fetch(endpoint, { method: editingDeviceId ? 'PATCH' : 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(payload) });
